const defaults=[['给自己买一束花','reward','❀'],['晒15分钟太阳','goal','☼'],['记录今天的心情','record','☷'],['吃一顿想吃的饭','reward','♨'],['拍一张喜欢的天空','record','☁'],['独自逛一次书店','reward','▤'],['写下喜欢自己的3个地方','record','♡'],['睡一个不用闹钟的觉','reward','☾'],['尝试一项新爱好','goal','✧'],['认真听完一张专辑','reward','♫'],['拒绝一次不想做的事','goal','⤴'],['给自己准备一份礼物','reward','♧'],['今天不必完成任何事','free','♡'],['去一个没去过的地方','goal','⌁'],['记录一件开心的小事','record','✎'],['看一部想看的电影','reward','▷'],['给未来的自己写封信','record','✉'],['尝试一道新菜','goal','♨'],['拍下今天最喜欢的瞬间','record','▧'],['和喜欢的人见面','reward','❋'],['散一次没有目的地的步','goal','⌇'],['做一次身体放松','reward','〰'],['记录最近的小小进步','record','↗'],['安排一次独处约会','goal','✶'],['为一件小事庆祝','reward','✷']];
const key='little-care-bingo-v2';const initial=[0,1,2,7,12,8,14,20,24];let cards=initial.map(i=>[...defaults[i]]),marks=[4],filter='all',editing=true;const $=s=>document.querySelector(s),types={record:'记录型',goal:'目标型',reward:'奖励型',free:'给自己的拥抱'};let shared=false;
function valid(s){return s&&Array.isArray(s.cards)&&[9,25].includes(s.cards.length)&&s.cards.every(c=>c===null||Array.isArray(c)&&c.length===3&&typeof c[0]==='string'&&c[0].trim().length>0&&c[0].length<=40&&defaults.some(d=>d[1]===c[1]&&d[2]===c[2]))&&Array.isArray(s.marks)&&s.marks.every(n=>Number.isInteger(n)&&n>=0&&n<s.cards.length)}
function restore(s){if(!valid(s))return false;if(s.cards.length===25){cards=initial.map(i=>s.cards[i]);marks=initial.flatMap((old,i)=>s.cards[old]&&s.marks.includes(old)?[i]:[])}else{cards=s.cards;marks=[...new Set(s.marks)].filter(i=>cards[i])}editing=s.mode!=='play'||cards.some(c=>!c);return true}
try{let s;if(location.hash.startsWith('#card=')){s=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(decodeURIComponent(location.hash.slice(6))),c=>c.charCodeAt(0))));shared=true}else{s=JSON.parse(localStorage.getItem(key)||localStorage.getItem('little-care-bingo-v1'))}restore(s);if(shared&&cards.every(Boolean))editing=false}catch{setTimeout(()=>toast('卡片未能读取，已为你准备一张新的'),400)}
function save(){try{localStorage.setItem(key,JSON.stringify({cards,marks,mode:editing?'edit':'play'}))}catch{}}const winningLines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
function lineCount(){return winningLines.filter(line=>line.every(i=>cards[i]&&marks.includes(i))).length}
function shuffleCards(){const pool=defaults.filter(c=>c[1]!=='free').map(c=>[...c]);for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}let next=pool.slice(0,8);next.splice(4,0,[...defaults[12]]);if(next.every((c,i)=>c[0]===cards[i]?.[0]))[next[0],next[1]]=[next[1],next[0]];cards=next;marks=[4];filter='all';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));save();render();toast('换好啦！新一轮从这里开始，点亮记录已重置 ♡')}
$('#shuffle').onclick=shuffleCards;
function render(){document.body.classList.toggle('is-editing',editing);$('#modeGuide').textContent=editing?'点击卡片替换，悬停 × 移除；点击空位添加。':'完成一件小事，就点亮一格；三格连线即可 Bingo。';$('#playActions').hidden=editing;$('#shuffle').hidden=!editing;$('#completeHint').hidden=!editing||cards.every(Boolean);$('#edit').disabled=editing&&cards.some(c=>!c);const grid=$('#grid');grid.replaceChildren();cards.forEach((c,i)=>{const slot=document.createElement('div');slot.className='card-slot';if(!c){const add=document.createElement('button');add.className='cell empty-cell';add.setAttribute('aria-label',`第 ${i+1} 格，添加卡片`);const plus=document.createElement('span');plus.className='empty-plus';plus.textContent='＋';const label=document.createElement('span');label.textContent='添加卡片';add.append(plus,label);add.onclick=()=>{editing=true;render();editCard(i)};slot.append(add);grid.append(slot);return}const b=document.createElement('button');b.className='cell'+(marks.includes(i)?' done':'')+(c[1]==='free'?' free':'')+(filter!=='all'&&c[1]!==filter?' dim':'');b.dataset.type=c[1];if(!editing)b.setAttribute('aria-pressed',String(marks.includes(i)));b.setAttribute('aria-label',editing?`${c[0]}，点击替换`:`${c[0]}，${marks.includes(i)?'已点亮':'未点亮'}`);for(const [cls,txt] of [['type',types[c[1]]],['symbol',c[2]],['label',c[0]],['number',String(i+1).padStart(2,'0')]]){const span=document.createElement('span');span.className=cls;span.textContent=txt;if(cls!=='label')span.setAttribute('aria-hidden','true');b.append(span)}b.onclick=()=>{if(editing){editCard(i);return}if(filter!=='all'&&c[1]!==filter){toast('这格属于'+types[c[1]]+'，切换「全部」后点亮它');return}let before=lineCount();marks=marks.includes(i)?marks.filter(x=>x!==i):[...marks,i];save();render();if(lineCount()>before){toast('Bingo！给认真爱自己的你，一个小奖励 ♡');$('#grid').classList.remove('bingo-pulse');void $('#grid').offsetWidth;$('#grid').classList.add('bingo-pulse')}};slot.append(b);if(editing){const remove=document.createElement('button');remove.className='remove-card';remove.setAttribute('aria-label',`移除${c[0]}`);remove.textContent='×';remove.onclick=()=>{cards[i]=null;marks=marks.filter(n=>n!==i);save();render();toast('留一个空位，给下一件想做的小事 ♡')};slot.append(remove)}grid.append(slot)});$('#edit').textContent=editing?'确认':'✎ 编辑计划'}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}function modal(html){$('#modal').classList.remove('picker-modal');$('#modal').removeAttribute('aria-labelledby');$('#modalContent').innerHTML=html;$('#modal').showModal()}$('#close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#edit').onclick=()=>{if(editing&&cards.some(c=>!c)){toast('先填满九宫格，再完成计划吧');return}editing=!editing;filter='all';save();render();if(!editing)toast('计划准备好了，从一件小事开始吧 ♡')};function activityKey(text){return text.normalize('NFKC').replace(/\s+/g,'').trim()}
function availableCards(i){const used=new Set(cards.filter((c,j)=>c&&j!==i).map(c=>activityKey(c[0])));const seen=new Set();return [cards[i],...defaults].filter(c=>{if(!c)return false;const k=activityKey(c[0]);if(used.has(k)||seen.has(k))return false;seen.add(k);return true}).map(c=>[...c])}
function applyCard(i,choice){if(cards.some((c,j)=>c&&j!==i&&activityKey(c[0])===activityKey(choice[0]))){toast('这件小事已经在卡片里了，换一个吧 ♡');return false}const changed=!cards[i]||cards[i].some((v,k)=>v!==choice[k]);cards[i]=[...choice];if(changed)marks=marks.filter(n=>n!==i);save();render();return true}
function editCard(i){let options=availableCards(i),selected=0;
modal('<div class="picker-heading"><span class="mini-label">A LITTLE SOMETHING FOR YOU</span><h3 id="pickerTitle">换一件关爱自己的小事</h3><p id="pickerStatus" aria-live="polite"></p></div><div class="picker-stage" id="pickerStage" aria-label="可选的自我关爱卡片"></div><div class="picker-controls"><button id="prevCard" class="picker-arrow" aria-label="上一张卡片">‹</button><button id="useCard" class="primary">使用这张卡片 ♡</button><button id="nextCard" class="picker-arrow" aria-label="下一张卡片">›</button></div><p class="picker-hint">左右切换，找到今天想送给自己的小事<br>已自动排除另外八格中的事项</p><button id="writeOwn" class="text-button">✎ 也可以自己写一件</button>');
$('#modal').classList.add('picker-modal');$('#modal').setAttribute('aria-labelledby','pickerTitle');
function preview(){const current=options[selected];$('#pickerStatus').textContent=`${current[0]} · ${selected+1} / ${options.length}`;const stage=$('#pickerStage');stage.replaceChildren();for(let offset=-2;offset<=2;offset++){const index=(selected+offset+options.length)%options.length,c=options[index],b=document.createElement('button');b.className='picker-card cell';b.dataset.type=c[1];b.dataset.offset=String(offset);if(c[1]==='free')b.classList.add('free');b.setAttribute('aria-label',`${c[0]}${offset===0?'，当前预览':''}`);b.tabIndex=offset===0?0:-1;for(const [cls,text] of [['type',types[c[1]]],['symbol',c[2]],['label',c[0]]]){const span=document.createElement('span');span.className=cls;span.textContent=text;if(cls!=='label')span.setAttribute('aria-hidden','true');b.append(span)}b.onclick=()=>{if(offset!==0){selected=index;preview()}};stage.append(b)}$('#useCard').textContent=cards[i]&&activityKey(current[0])===activityKey(cards[i][0])?'保留这张卡片 ♡':'使用这张卡片 ♡'}
function move(delta){selected=(selected+delta+options.length)%options.length;preview()}
$('#prevCard').onclick=()=>move(-1);$('#nextCard').onclick=()=>move(1);$('#useCard').onclick=()=>{if(applyCard(i,options[selected])){$('#modal').close();toast('这一格，换成新的小小关爱 ♡')}};
$('#modal').onkeydown=e=>{if(!$('#modal').classList.contains('picker-modal'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowLeft'?-1:1)}};
let startX=null;$('#pickerStage').onpointerdown=e=>{startX=e.clientX};$('#pickerStage').onpointerup=e=>{if(startX!==null&&Math.abs(e.clientX-startX)>45)move(e.clientX<startX?1:-1);startX=null};$('#pickerStage').onpointercancel=()=>{startX=null};
$('#writeOwn').onclick=()=>{const base=[...options[selected]];$('#modal').close();modal('<h3>这一格，留给自己</h3><p>一件小事就好，不必太用力。</p><label for="cardText">自我关爱小事（最多 40 字）</label><textarea id="cardText" rows="3" maxlength="40"></textarea><p id="editError" class="edit-error" role="alert"></p><button class="primary" id="saveCard">保存这一格 ♡</button><button class="secondary" id="backPicker">返回选卡</button>');$('#cardText').value=cards[i]?cards[i][0]:'';$('#saveCard').onclick=()=>{const text=$('#cardText').value.trim();if(!text){$('#editError').textContent='写下一件想为自己做的小事吧';return}if(cards.some((c,j)=>c&&j!==i&&activityKey(c[0])===activityKey(text))){$('#editError').textContent='这件小事已在其他格子里了，换一个吧 ♡';return}if(applyCard(i,[text,base[1],base[2]]))$('#modal').close()};$('#backPicker').onclick=()=>{$('#modal').close();editCard(i)}};
preview();$('#nextCard').focus()}


function shareUrl(){const bytes=new TextEncoder().encode(JSON.stringify({cards,marks,mode:editing?'edit':'play'}));return location.origin+location.pathname+'#card='+encodeURIComponent(btoa(Array.from(bytes,b=>String.fromCharCode(b)).join('')))}async function copy(t){try{await navigator.clipboard.writeText(t);toast('链接已复制，把这份温柔分享出去吧 ♡')}catch{const input=$('#shareLink');input.focus();input.select();toast('请长按或按 Ctrl/Cmd+C 复制链接')}}$('#share').onclick=()=>{modal('<span class="mini-label">A LITTLE CARE TO SHARE</span><h3 style="margin-top:12px">把温柔，分享给另一个人。</h3><p>链接包含这张卡片的内容和当前进度。朋友打开后，可以拥有自己的打卡记录。</p><label for="shareLink">你的专属卡片链接</label><input id="shareLink" readonly><button id="copy" class="primary">复制分享链接 ↗</button><button id="nativeShare" class="secondary">更多分享方式</button><p style="font-size:11px">也可以下载为图片，发给朋友或打印下来。</p>');$('#shareLink').value=shareUrl();$('#copy').onclick=()=>copy(shareUrl());$('#nativeShare').onclick=async()=>{if(navigator.share){try{await navigator.share({title:'给自己的 9 件小事 · 自我关爱 Bingo',text:'把时间分一点给自己，和我一起慢慢点亮这张卡吧 ♡',url:shareUrl()})}catch(e){if(e.name!=='AbortError')copy(shareUrl())}}else copy(shareUrl())}};
function wrap(ctx,text,max){let rows=[],s='';for(const ch of text){if(ctx.measureText(s+ch).width>max&&s){rows.push(s);s=ch}else s+=ch}if(s)rows.push(s);return rows}function rounded(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
$('#download').onclick=async()=>{const btn=$('#download');btn.disabled=true;btn.textContent='正在制作图片…';try{await document.fonts.ready;const c=document.createElement('canvas');c.width=1800;c.height=1900;const ctx=c.getContext('2d');ctx.fillStyle='#faf7ef';ctx.fillRect(0,0,c.width,c.height);ctx.textAlign='center';ctx.fillStyle='#8b9078';ctx.font='22px sans-serif';ctx.fillText('L I T T L E   C A R E   C L U B',900,95);ctx.fillStyle='#514c43';ctx.font='500 78px "Noto Serif SC", serif';ctx.fillText('好好爱自己',900,205);ctx.font='32px "Noto Serif SC", serif';ctx.fillText('也可以是一场小小的游戏。',900,272);ctx.font='23px sans-serif';ctx.fillStyle='#91867c';ctx.fillText('把时间分一点给自己，把普通日子过得柔软一点。',900,332);const colors={record:'#dee7d7',goal:'#dee7f1',reward:'#f0dde2',free:'#e8ddcc'};cards.forEach((card,i)=>{const x=90+i%3*546,y=405+Math.floor(i/3)*400,w=528,h=382,done=marks.includes(i);if(!card){ctx.fillStyle='#f3efe4';rounded(ctx,x,y,w,h,14);ctx.strokeStyle='#c8bda6';ctx.lineWidth=2;ctx.setLineDash([10,10]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#a09689';ctx.font='56px sans-serif';ctx.fillText('＋',x+w/2,y+150);ctx.font='25px sans-serif';ctx.fillText('留一点空白给自己',x+w/2,y+224);return}ctx.fillStyle=done?'#d0d9c3':colors[card[1]];rounded(ctx,x,y,w,h,14);if(done){ctx.strokeStyle='#899477';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#73815e';ctx.font='28px sans-serif';ctx.fillText('✓',x+w-24,y+34)}ctx.fillStyle='#817d71';ctx.font='16px sans-serif';ctx.textAlign='left';ctx.fillText(types[card[1]],x+18,y+30);ctx.textAlign='center';ctx.fillStyle='#74765f';ctx.font='57px serif';ctx.fillText(card[2],x+w/2,y+143);ctx.fillStyle='#514c43';ctx.font='30px "Noto Serif SC", sans-serif';const rows=wrap(ctx,card[0],w-38);rows.forEach((t,j)=>ctx.fillText(t,x+w/2,y+218+j*39));ctx.fillStyle='#9b968a';ctx.font='14px sans-serif';ctx.fillText(String(i+1).padStart(2,'0'),x+w-22,y+h-14)});ctx.fillStyle='#6c775f';ctx.font='25px sans-serif';ctx.fillText(`已点亮 ${marks.length} / 9 格  ·  ${lineCount()} 条 Bingo`,900,1680);ctx.fillStyle='#91867c';ctx.font='26px "Noto Serif SC", serif';ctx.fillText('今天不必完成任何事。你本来就值得被好好对待。',900,1760);ctx.font='17px sans-serif';ctx.fillText('自我关爱 BINGO  ·  每一小步都算数 ♡',900,1820);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('export');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='好好爱自己-Bingo.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('卡片已生成，愿你把温柔带在身边 ♡')}catch{toast('图片生成失败，请再试一次')}finally{btn.disabled=false;btn.textContent='↓ 下载我的卡片'}};
render();if(shared){save();history.replaceState(null,'',location.pathname+location.search);setTimeout(()=>toast('收到一份小小关爱，开始你的专属打卡吧 ♡'),500)}
